ns.Data.Rotations = {
  enhancement = "Before combat: Windfury Weapon (from 30; before that Rockbiter Weapon solo, Flametongue Weapon in groups), Lightning Shield (or Water Shield if talented), totems: Strength of Earth Totem, Magma Totem (Searing Totem if mana is short), Mana Spring Totem, Windfury Totem (it now stacks with your own Windfury Weapon, so drop it even solo). Single target: Magma Totem if not active (Searing Totem if mana is limited) > Flame Shock if missing on the target > Rage of the Farseer (with trinkets and racials such as Berserking) > Stormstrike on cooldown (8 s; react to Improved Stormstrike resets) > Lightning Bolt only at 5 Maelstrom Weapon stacks (instant, does not reset the swing timer; never below 5) > Earth Shock (spends the Stormstrike debuff; Frost Shock if threat is a problem) > Fire Nova with a Fire totem active. AoE: Magma Totem > Fire Nova on cooldown > Flame Shock cycling targets > Rage of the Farseer > Stormstrike > Lightning Bolt at 5 stacks > Earth Shock. Leveling before talents: pull with rank 1 Lightning Bolt, Earth Shock on cooldown (it also interrupts), Fire Nova with a Fire totem and spare mana, then auto-attack; Healing Wave after pulls, Lesser Healing Wave when in danger; Ghost Wolf between fights from 20.",
  elemental = "Pre-place totems (Call of the Elements; drop Searing Totem last for single target, Magma Totem for 3+ targets). Single target: Flame Shock, refresh when it falls off > Lightning Mastery with racials, potions and trinkets > Chain Lightning outside the Lightning Mastery window (in long fights only with Clearcasting) > Lightning Bolt as filler. 3+ targets: Lightning Mastery > Chain Lightning on cooldown > Fire Nova on cooldown > Flame Shock on targets without it > Lightning Bolt (skip Flame Shock and Lightning Bolt if mana will not last). Leveling: Lightning Shield between pulls (Water Shield once talented), open from max range with Lightning Bolt or Chain Lightning, Fire Nova from 12 and Chain Lightning from 32 for packs, Earth Shock to interrupt casters.",
  restoration = "Water Shield (Lightning Shield before you have it) and totems before the pull. Single target: Riptide on the most injured target on cooldown > Healing Wave (downrank when damage is light) > Lightning Bolt for damage only when no healing is needed. Group damage: Riptide > Chain Heal on an injured target with Riptide > Fire Nova and Chain Lightning only if mana allows. Nature's Swiftness + Healing Wave for emergencies; Mana Tide Totem at about 80% mana. Earth Shock is the only healer interrupt. Not recommended for solo leveling (play Enhancement solo).",
  mana = "Spirit-based mana regen pauses for 5 s after you spend any mana, including instants and totems. Let auto-attacks finish low targets instead of a last spell; refresh Lightning Shield right after the last spell of a fight; stop casting and let mana build when safe. In-combat regen: Improved Stormstrike (50% regen while casting for 15 s after Stormstrike), Mindfulness (50% while casting), Water Shield (2% of max mana per globe). Mana Spring Totem for the group. Totemic Recall refunds 25% of your totems' mana; Call of the Elements costs all four totems at once; Totemic Call is very expensive and on the GCD, so usually recall and re-drop instead. Spend Clearcasting on expensive spells (Chain Lightning, Fire Nova). A Paladin's Judgement of Wisdom carries Enhancement mana in groups. Always carry water.",
  imbues = "Nov 10/11 hotfix first: weapon imbues and weapon totems now stack (Windfury Weapon + Windfury Totem both proc), and Blizzard wants Windfury at the heart of Enhancement. Enhancement: Windfury Weapon from 30, always (Icy Veins Nov 13: the go-to imbue; Flametongue builds are unlikely to compete). Before 30: Rockbiter Weapon solo, Flametongue Weapon in groups. Elemental/Restoration: Flametongue Weapon (Wowhead leveling pages, pre-hotfix). Imbues last 60 min and sit alongside stones and oils.",
  totems = "One totem per element; 1.0 s GCD; buff totems last 5 min. Enhancement: Strength of Earth Totem, Magma Totem (Searing Totem if mana-limited), Mana Spring Totem, Windfury Totem. Casters in groups: Strength of Earth Totem and Windfury Totem with melee, Searing Totem (Magma Totem vs 3+), Mana Spring Totem; Grace of Air Totem with other Shamans. Fire Nova needs an active Fire totem near the enemies. Windfury Totem and Flametongue Totem are exclusive. Grounding Totem vs casters, Tremor Totem vs fear/charm/sleep, Poison Cleansing Totem / Disease Cleansing Totem when needed, Earthbind Totem to kite, Stoneclaw Totem to soak an extra mob. Totemic Recall when moving on.",
  sources = { "https://www.icy-veins.com/wow-forever/enhancement-shaman-melee-dps-pve-rotation-cooldowns-abilities", "https://www.icy-veins.com/wow-forever/enhancement-shaman-leveling", "https://www.icy-veins.com/wow-forever/elemental-shaman-ranged-dps-pve-rotation-cooldowns-abilities", "https://www.icy-veins.com/wow-forever/elemental-shaman-leveling", "https://www.icy-veins.com/wow-forever/restoration-shaman-healer-pve-rotation-cooldowns-abilities", "https://www.icy-veins.com/wow-forever/restoration-shaman-leveling", "https://news.blizzard.com/en-us/article/24315281/wow-forever-hotfixes-november-13-2026", "https://www.wowhead.com/forever/guide/classes/shaman/elemental/dps-leveling-tips", "https://www.wowhead.com/forever/guide/classes/shaman/restoration/healer-leveling-tips", "https://news.blizzard.com/en-us/article/24302097/world-of-warcraft-forever-class-deep-dives-mage-and-shaman" },
  source_url = "https://www.icy-veins.com/wow-forever/enhancement-shaman-melee-dps-pve-rotation-cooldowns-abilities",
  checked = "2026-11-14",
